-- =====================================================================================
-- Smooth forecast mock: small row changes in the past dispensing data so the Predictive Medicine Demand
-- snapshots move day by day (generated by backend/scripts/smoothForecastMock.js, seeded: same output every run).
-- The forecast formula is NOT changed. Run it AFTER the other seed files (seed_nov_2026_forecast_mock.sql,
-- seed_snapshot_stock_mock.sql). Added units are direct_dispensation rows DSMTH-*; undo data is in
-- backend/scripts/smoothForecastMock.backup.json (node scripts/smoothForecastMock.js --apply undoes and redoes it).
-- Run with: mysql --default-character-set=utf8mb4 -u root -p < seed_smooth_forecast_mock.sql
-- =====================================================================================
USE ClinicManagementSystem;
SET time_zone = '+08:00';
SET SQL_SAFE_UPDATES = 0;
START TRANSACTION;

DELETE FROM direct_dispensation WHERE direct_dispense_id LIKE 'DSMTH-%';

